namespace ghidra.app.plugin.core.decompile.actions;

using docking;
using ghidra.app.decompiler;
using ghidra.app.decompiler.component;
using ghidra.app.plugin.core.decompile;
using ghidra.framework.plugintool;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.pcode;
using ghidra.program.model.pcode;
using ghidra.util;

public class DecompilerStructureVariableAction : CreateStructureVariableAction {

	public DecompilerStructureVariableAction(string owner, PluginTool tool,
			DecompilerController controller) : base(owner, tool, controller)
    {
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {

		if (!(context is DecompilerActionContext)) {
			return false;
		}

		Function function = controller.getFunction();
		if (function == null || function is UndefinedFunction) {
			return false;
		}

		DataType dt = null;
		bool isThisParam = false;

		// get the data type at the location and see if it is OK
		DecompilerPanel decompilerPanel = controller.getDecompilerPanel();
		ClangToken tokenAtCursor = decompilerPanel.getTokenAtCursor();
		if (tokenAtCursor == null) {
			return false;
		}
		int maxPointerSize = controller.getProgram().getDefaultPointerSize();
		HighVariable var = tokenAtCursor.getHighVariable();
		if (var != null && !(var is HighConstant)) {
			dt = var.getDataType();
			isThisParam = DecompilerUtils.isThisParameter(var, function);
		}

		if (dt == null || dt.getLength() > maxPointerSize) {
			return false;
		}

		adjustCreateStructureMenuText(dt, isThisParam);
		return true;
	}
}
